class AdminAnalyticsTrendPoint { const AdminAnalyticsTrendPoint({required this.date, required this.activeUsers, required this.sessions, required this.screenViews, required this.interactions}); final String date; final int activeUsers; final int sessions; final int screenViews; final int interactions; factory AdminAnalyticsTrendPoint.fromJson(Map<String, dynamic> json) => AdminAnalyticsTrendPoint(date: json['date'] as String, activeUsers: (json['activeUsers'] as num).toInt(), sessions: (json['sessions'] as num).toInt(), screenViews: (json['screenViews'] as num).toInt(), interactions: (json['interactions'] as num).toInt()); }
class AdminAnalyticsSummary { const AdminAnalyticsSummary({required this.dau, required this.wau, required this.mau, required this.newUsers, required this.returningUsers, required this.sessions, required this.screenViews, required this.interactions, required this.navigationEvents, required this.engagementTrend}); final int dau, wau, mau, newUsers, returningUsers, sessions, screenViews, interactions, navigationEvents; final List<AdminAnalyticsTrendPoint> engagementTrend; factory AdminAnalyticsSummary.fromJson(Map<String, dynamic> json) => AdminAnalyticsSummary(dau: (json['dau'] as num).toInt(), wau: (json['wau'] as num).toInt(), mau: (json['mau'] as num).toInt(), newUsers: (json['newUsers'] as num).toInt(), returningUsers: (json['returningUsers'] as num).toInt(), sessions: (json['sessions'] as num).toInt(), screenViews: (json['screenViews'] as num).toInt(), interactions: (json['interactions'] as num).toInt(), navigationEvents: (json['navigationEvents'] as num).toInt(), engagementTrend: (json['engagementTrend'] as List<dynamic>).map((item) => AdminAnalyticsTrendPoint.fromJson(item as Map<String, dynamic>)).toList(growable: false)); }
